import React, { useState } from 'react';
import { ChevronRight, Circle as HelpCircle2, X } from 'lucide-react';

const FAQ_DATA = [
  {
    id: 1,
    question: 'What is Hartley & Rowe\'s specialization?',
    answer: 'Hartley & Rowe specializes in high-asset divorce proceedings, complex child custody disputes, and property conveyancing. Our team handles cases involving multi-million pound estates, international asset tracing, and high-profile clients.',
  },
  {
    id: 2,
    question: 'How are legal fees structured for a divorce?',
    answer: 'We offer a fixed-fee package for initial consultation and document preparation, followed by hourly rates for extensive mediation or court representation. A detailed breakdown is provided before commencing any work.',
  },
  {
    id: 3,
    question: 'Can I request a contingency fee arrangement?',
    answer: 'We do not offer contingency fees for divorce or custody cases. However, we may negotiate a fixed-fee retainer for specific tasks, subject to our case evaluation.',
  },
  {
    id: 4,
    question: 'How long does a typical custody case take?',
    answer: 'Custody disputes can vary widely. Simple agreements might be resolved within a few months, while more contentious cases could extend over 18 months or longer, depending on court schedules and evidence submission deadlines.',
  },
  {
    id: 5,
    question: 'Are there additional costs beyond legal fees?',
    answer: 'Yes, there may be filing fees, expert witness fees, and third-party valuation costs. These are billed separately and detailed invoices are issued regularly to maintain transparency.',
  },
];

export default function Faq() {
  const [isOpen, setIsOpen] = useState<number[]>([]);

  const toggleAccordion = (id: number) => {
    if (isOpen.includes(id)) {
      setIsOpen(isOpen.filter((accId) => accId !== id));
    } else {
      setIsOpen([id]);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-10 bg-slate-950 text-slate-100 font-sans">
      <div className="mb-20 text-center">
        <h2 className="text-3xl sm:text-4xl font-extrabold tracking-tight text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 mb-4">
          Frequently Asked Questions
        </h2>
        <p className="text-slate-400 text-sm sm:text-base mb-12">
          Get answers to common questions about legal fees, practice areas, and more.
        </p>
      </div>

      {/* Accordion Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {FAQ_DATA.map((faq) => {
          const isExpanded = isOpen.includes(faq.id);
          return (
            <div
              key={faq.id}
              className="group relative rounded-2xl bg-slate-900/50 backdrop-blur-xl border border-white/10 p-6 sm:p-8 transition-all duration-300 hover:border-white/20 hover:shadow-xl hover:shadow-indigo-900/20"
            >
              {/* Top Decorative Gradient Border */}
              <div className="absolute -top-1 -right-1 -left-1 h-0.5 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500" />

              {/* Header & Arrow */}
              <div className="flex items-start justify-between pb-4 border-b border-white/10">
                <h3 className="text-slate-200 flex items-center gap-2 cursor-pointer select-none">
                  {faq.question}
                  <span className="flex items-center gap-1">
                    <ChevronRight className={`w-4 h-4 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} />
                  </span>
                </h3>
                {/* Accordion Control Button */}
                <button
                  onClick={() => toggleAccordion(faq.id)}
                  className="p-1 rounded-xl bg-slate-900/20 hover:bg-slate-900/30 transition-colors text-slate-400 hover:text-white"
                >
                  <span className="sr-only">Toggle Accordion</span>
                  <X className="w-4 h-4" />
                </button>
              </div>

              {/* Accordion Content */}
              {isExpanded && (
                <div className="mt-4 max-w-md space-y-4 text-slate-400">
                  <p>{faq.answer}</p>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Scale, Gavel, ShieldCheck, Users, FileText, MapPin, Sparkles, ArrowRight, Phone, Mail } from 'lucide-react';

const freeConsultation = {
  title: 'Free Initial Consultation',
  icon: Sparkles,
  description: 'Discuss your case with one of our expert solicitors at no cost. No obligation to proceed.',
  callToAction: 'Schedule Now',
};

const hourlyRate = {
  title: 'Hourly Rate Representation',
  icon: DollarSign,
  description: 'Pay as you go for legal advice and representation. Fees billed in 15-minute increments.',
  callToAction: 'Start Consultation',
};

const fullRetainer = {
  title: 'Full-Service Retainer',
  icon: ShieldCheck,
  description: 'Secure peace of mind with a fixed monthly fee. Includes priority access and dedicated support.',
  callToAction: 'Learn More',
};

export default function Fees() {
  const [selected, setSelected] = useState(null);

  const toggleSelection = (id) => {
    if (selected === id) return setSelected(null);
    setSelected(id);
  };

  const [isFormOpen, setIsFormOpen] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '' });

  const validate = (formData) => {
    const errors = {};
    if (!formData.name.trim()) errors.name = 'Name is required';
    if (!formData.email || !formData.email.includes('@')) errors.email = 'Valid email is required';
    if (!formData.phone || !formData.phone.startsWith('+44')) errors.phone = 'Valid UK phone number is required';
    return errors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const errors = validate(formData);
    if (Object.keys(errors).length === 0) {
      alert('Form submitted successfully!');
      setIsFormOpen(false);
    } else {
      console.error('Validation errors:', errors);
    }
  };

  return (
    <div className="min-h-[80vh] bg-slate-950 p-6 sm:p-8 lg:p-12 font-sans text-slate-100">
      {/* Header Section */}
      <div className="max-w-7xl mx-auto text-center pb-12 sm:pb-16">
        <h2 className="mb-4 text-3xl sm:text-4xl font-extrabold tracking-tight text-slate-200 bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-500">
          <span className="inline-block animate-pulse bg-white/10 rounded-xl px-3 py-1">Transparent Pricing</span>
        </h2>
        <p className="text-lg sm:text-xl text-slate-400 max-w-md mx-auto mb-8">
          At Hartley & Rowe, our commitment is to provide clear, upfront costs tailored to your unique legal journey.
        </p>
      </div>

      {/* Card Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 mx-auto max-w-7xl">
        {[
          { id: 'free', data: freeConsultation },
          { id: 'hourly', data: hourlyRate },
          { id: 'retainer', data: fullRetainer },
        ].map((card) => (
          <div
            key={card.id}
            className="group relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:border-white/20"
          >
            {/* Card Header */}
            <div className="mb-6 flex flex-col justify-between">
              <div className="flex items-center justify-between">
                <span className="inline-flex items-center rounded-full bg-white/10 px-3 py-1 text-xs font-medium tracking-wider text-slate-400 ring-1 ring-white/20 transition-all duration-300 group-hover:ring-white/40">
                  {card.data.icon({ size: 24, className: 'text-slate-400 group-hover:text-white' })}
                </span>
                <span className="flex items-center gap-1 self-start">
                  <span className="bg-gradient-to-r from-indigo-500 to-violet-600 rounded-full px-2.5 py-1 text-[10px] font-bold uppercase text-slate-200">{card.id.toUpperCase()}</span>
                  <span className="text-[10px] font-bold uppercase text-slate-400">Pricing Tier</span>
                </span>
              </div>
              <h3 className="mb-2 text-xl font-semibold text-slate-100 transition-colors group-hover:text-white">{card.data.title}</h3>
            </div>

            {/* Card Body */}
            <div className="space-y-2 text-sm text-slate-400">
              <p>{card.data.description}</p>
            </div>

            {/* Call to Action */}
            <button
              type="button"
              onClick={() => toggleSelection(card.id)}
              className="mt-6 w-full rounded-xl bg-white/5 px-4 py-3 text-sm font-medium text-slate-200 hover:text-white transition-all duration-300 active:scale-[0.98] active:shadow-inner"
            >
              {card.data.callToAction}
            </button>
          </div>
        ))}
      </div>

      {/* Contact Form */}
      <div className="mt-12 max-w-sm mx-auto bg-white/5 p-8 rounded-2xl border border-white/10 backdrop-blur-xl shadow-2xl transition-transform duration-300 hover:scale-[1.02]">
        <div className="mb-8 text-center">
          <h3 className="mb-4 text-2xl font-bold text-slate-100 tracking-tight">Contact Our Team</h3>
          <p className="text-sm text-slate-400">Ready to take the next step?</p>
        </div>
        {isFormOpen ? (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="mb-4">
              <label htmlFor="name" className="block text-sm font-medium text-slate-400">Full Name</label>
              <input
                id="name"
                name="name"
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500 transition-all duration-200"
                placeholder="John Doe"
                required
              />
            </div>
            <div className="mb-4">
              <label htmlFor="email" className="block text-sm font-medium text-slate-400">Email Address</label>
              <input
                id="email"
                name="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500 transition-all duration-200"
                placeholder="john.doe@example.com"
                required
              />
            </div>
            <div className="mb-4">
              <label htmlFor="phone" className="block text-sm font-medium text-slate-400">Phone Number</label>
              <input
                id="phone"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500 transition-all duration-200"
                placeholder="+44 113 456 7890"
                required
              />
            </div>
            <button
              type="submit"
              disabled={Object.keys(validate(formData)).length > 0}
              className="w-full rounded-lg bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-600 px-3 py-2 text-sm font-medium text-white shadow-lg transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-500/30 active:scale-[0.98] active:shadow-indigo-500/10"
            >
              {isFormLoading ? 'Sending...' : 'Send Message'}
            </button>
          </form>
        ) : (
          <div className="relative overflow-hidden rounded-2xl bg-white/10 p-8 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:shadow-indigo-500/10">
            <div className="absolute -top-24 -right-24 w-96 rounded-xl bg-white/20 p-6 shadow-lg transition-all duration-300 group-hover:-top-20 group-hover:-right-20">
              <h4 className="mb-4 text-xl font-semibold text-slate-100">Get Started Today</h4>
              <p className="text-sm text-slate-400">Free initial consultation included.</p>
            </div>
            <button
              onClick={() => setIsFormOpen(true)}
              className="w-full rounded-xl bg-white/5 border border-white/10 p-4 text-center font-semibold text-slate-200 transition-all duration-300 hover:bg-white/10 active:scale-[0.98]"
            >
              <div className="flex items-center justify-center gap-2">
                <Phone className="text-slate-400" />
                <span>Book a Call</span>
              </div>
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Scale, Gavel, ShieldCheck, Users, FileText, Landmark, ChevronRight, Sparkles } from 'lucide-react';

const PRACTICE_AREAS = [
  {
    id: '1',
    title: 'Business & Corporate',
    description: 'Safeguarding your corporate interests with the precision of a high-flying jet.',
    icon: Scale,
    badge: 'Corporate Litigator'
  },
  {
    id: '2',
    title: 'Family & Divorce',
    description: 'Navigating the complexities of family law with compassionate guidance.',
    icon: Gavel,
    badge: 'Divorce Mediator'
  },
  {
    id: '3',
    title: 'Real Estate',
    description: 'Securing your property transactions with a keen eye for detail and value.',
    icon: Landmark,
    badge: 'Conveyancing Expert'
  },
  {
    id: '4',
    title: 'Personal Injury',
    description: 'Empowering victims to seek justice and recover from life-altering incidents.',
    icon: ShieldCheck,
    badge: 'Catastrophe Advocate'
  },
  {
    id: '5',
    title: 'Litigation & Dispute Resolution',
    description: 'Championing your case through the adversarial arena with relentless vigor.',
    icon: Users,
    badge: 'Litigation Strategist'
  }
];

export default function PracticeAreas() {
  const [currentArea, setCurrentArea] = useState('1');
  const [isHovered, setIsHovered] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);

  return (
    <div className="w-full bg-slate-950 text-slate-100 min-h-screen p-6 sm:p-8 lg:p-12">
      <div className="max-w-7xl mx-auto">
        <div className="mb-20">
          <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-center text-slate-200 mb-6">
            <span className="bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 bg-clip-text text-transparent">
              Our Expertise
            </span>
            <span className="ml-2 font-normal">Delivering tailored solutions for your unique legal needs.</span>
          </h2>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8 lg:gap-12">
          {PRACTICE_AREAS.map((area) => {
            const { id, title, description, icon: Icon, badge } = area;
            const isCurrent = id === currentArea;
            const isHoveredState = isHovered || isCurrent;

            return (
              <div
                key={id}
                className="group relative overflow-hidden rounded-2xl border border-white/10 bg-slate-900/80 backdrop-blur-xl p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl"
                onMouseEnter={() => setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
              >
                <div className="absolute inset-0 bg-slate-950/90 opacity-0 group-hover:opacity-80 transition-opacity duration-300" />
                <div className="relative flex items-center justify-between pb-6">
                  <div className="flex items-center space-x-2">
                    <div className="p-2 rounded-xl bg-indigo-500/20 text-indigo-400 border border-indigo-500/30">
                      <Icon size={24} className="w-5 h-5" />
                    </div>
                    <h3 className="font-semibold text-slate-100">{title}</h3>
                  </div>
                  <button
                    className="flex items-center gap-1 text-slate-400 hover:text-slate-300 transition-colors active:scale-95"
                    onClick={() => setIsExpanded(!isExpanded)}
                  >
                    <Sparkles size={14} className="w-3 h-3" />
                    {isExpanded ? 'Minimize' : 'Expand'}
                  </button>
                </div>

                {isExpanded && (
                  <div className="space-y-4">
                    <p className="text-slate-400">{description}</p>
                    <div className="flex items-center gap-2 mt-4">
                      <div className="p-2 rounded-xl bg-blue-500/10 text-blue-400 border border-blue-500/20">
                        <Users size={14} className="w-3 h-3" />
                      </div>
                      <span className="text-slate-400">{badge}</span>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
